    static CodexChapterAddressablesRepair() { EditorApplication.delayCall += AutoApply; }
    static void AutoApply() { if (!File.Exists(Report)) Apply(); }
    [MenuItem("Tools/VNovelizer/Repair Chapter Addressables")]
    public static void Apply()
    {
        if (EditorApplication.isCompiling || EditorApplication.isUpdating) { EditorApplication.delayCall += AutoApply; return; }
        try {
            var settings = AddressableAssetSettingsDefaultObject.Settings;
            if (settings == null) throw new Exception("Addressables settings missing");
            foreach (var item in Items) {
                var path = AssetDatabase.GUIDToAssetPath(item.Guid);
                if (!path.StartsWith("Assets/RemoteContent/", StringComparison.OrdinalIgnoreCase) || AssetDatabase.LoadMainAssetAtPath(path) == null)
                    throw new Exception("Missing RemoteContent asset: " + item.Address + " at " + path);
                if (settings.FindGroup(item.Group) == null) throw new Exception("Missing group: " + item.Group);
            }
            foreach (var item in Items) {
                var group = settings.FindGroup(item.Group);
                var entry = settings.CreateOrMoveEntry(item.Guid, group);
                entry.SetAddress(item.Address);
                // Preserve existing labels and restore each directory label used by the project.
                for (int slash = item.Address.IndexOf('/'); slash >= 0; slash = item.Address.IndexOf('/', slash + 1))
                    entry.SetLabel(item.Address.Substring(0, slash), true, true);
                entry.SetLabel("chapter1_required", item.Group == "Chapter1-Remote", true);
                entry.SetLabel("chapter2_optional", item.Group == "Chapter2-Remote", true);
                EditorUtility.SetDirty(group);
            }
            EditorUtility.SetDirty(settings);
            AssetDatabase.SaveAssets();
            foreach (var item in Items) {
                var entry = settings.FindAssetEntry(item.Guid);
                if (entry == null || entry.parentGroup.Name != item.Group || entry.address != item.Address)
                    throw new Exception("Verification failed: " + item.Address);
                for (int slash = item.Address.IndexOf('/'); slash >= 0; slash = item.Address.IndexOf('/', slash + 1))
                    if (!entry.labels.Contains(item.Address.Substring(0, slash)))
                        throw new Exception("Missing directory label: " + item.Address);
                var chapterLabel = item.Group == "Chapter1-Remote" ? "chapter1_required" : "chapter2_optional";
                if (!entry.labels.Contains(chapterLabel)) throw new Exception("Missing chapter label: " + item.Address);
            }
            File.WriteAllText(Report, DateTime.Now.ToString("O") + "\nVerified via Unity Addressables API: " + Items.Length + " entries.\n");
            Debug.Log("Chapter Addressables and labels repaired and verified: " + Items.Length + " entries.");
        } catch (Exception e) { Debug.LogException(e); }
    }
